def transform(grid):
    """Mark one-cell neighborhoods around closed 1-color contours."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find 4-connected components of the contour color.
    seen1 = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen1:
                continue
            q = [(r, c)]
            seen1.add((r, c))
            comp = set()
            while q:
                x, y = q.pop()
                comp.add((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in seen1:
                        seen1.add((nx, ny))
                        q.append((nx, ny))
            components.append(comp)

    # Locate all zero regions. Regions reaching the canvas edge are exterior;
    # enclosed regions are cavities. Color their inner boundary with 3.
    seen0 = set()
    exterior = set()
    cavities = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen0:
                continue
            q = [(r, c)]
            seen0.add((r, c))
            region = set()
            touches_edge = False
            while q:
                x, y = q.pop()
                region.add((x, y))
                touches_edge |= x == 0 or y == 0 or x == h - 1 or y == w - 1
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen0:
                        seen0.add((nx, ny))
                        q.append((nx, ny))
            if touches_edge:
                exterior |= region
            else:
                cavities.append(region)

    # Only contours enclosing a cavity are active. Mark cavity boundary cells 3;
    # mark the 8-neighbor exterior halo of the same contour 2.
    for comp in components:
        holes = []
        for region in cavities:
            boundary = {
                (r, c)
                for r, c in region
                if any((r + dr, c + dc) in comp for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)))
            }
            if boundary:
                holes.append((region, boundary))
        if not holes:
            continue
        for region, boundary in holes:
            for r, c in boundary:
                out[r][c] = 3
        for r, c in comp:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) in exterior:
                        out[nr][nc] = 2
    return out


